        //         "price": 6294.77
        //     }
        //
        let mut microtimestamp: Value = self.safe_integer_k(trade.clone(), "microtimestamp", &[Value::Int(0)]);
        let mut id: Value = self.safe_string_k(trade.clone(), "id", &[]);
